-- Đợt 2: thêm 12 tình huống + 54 từ vựng (chạy SAU seed_more.sql). Chạy lại không bị trùng.
INSERT INTO public.scenarios (category_id, title, title_zh, description, situation, learning_objectives, difficulty,
  estimated_minutes, ai_role, ai_role_zh, ai_personality, initial_message, suggested_phrases, is_published)
SELECT c.id, s.title, s.title_zh, s.description, s.situation, s.objectives, s.difficulty, s.minutes,
       s.ai_role, s.ai_role_zh, s.personality, s.initial_message, s.phrases::jsonb, TRUE
FROM (VALUES
 ('Văn phòng - Hành chính','Soạn email công việc','写工作邮件','Trao đổi nội dung và cách viết email gửi khách hàng.',
  'Đồng nghiệp nhờ bạn soạn email xác nhận lịch họp với khách hàng Trung Quốc.',
  ARRAY['Dùng câu mở đầu và kết thúc email','Xác nhận thời gian','Giữ giọng văn lịch sự'],'intermediate',12,
  'Đồng nghiệp','同事','Thân thiện, hay góp ý cách dùng từ cho lịch sự.','请帮我写一封邮件给客户，确认明天的会议时间，可以吗？',
  '[{"zh":"尊敬的王经理，您好。","vi":"Kính gửi giám đốc Vương."},{"zh":"请您确认一下会议时间。","vi":"Xin ngài xác nhận thời gian họp."}]'),
 ('Kinh doanh - Bán hàng','Chăm sóc khách sau bán','售后回访','Hỏi thăm mức độ hài lòng và ghi nhận phản hồi.',
  'Bạn gọi điện cho khách vừa mua hàng để hỏi họ dùng sản phẩm thế nào.',
  ARRAY['Hỏi thăm khách','Ghi nhận phản hồi','Đề nghị hỗ trợ thêm'],'intermediate',12,
  'Khách hàng','客户','Khá hài lòng nhưng có một vài góp ý nhỏ.','你好，我上周在你们这里买了一台机器。',
  '[{"zh":"请问您用得怎么样？","vi":"Xin hỏi anh/chị dùng thế nào?"},{"zh":"有问题请随时联系我们。","vi":"Có vấn đề cứ liên hệ chúng tôi bất cứ lúc nào."}]'),
 ('Kinh doanh - Bán hàng','Giới thiệu sản phẩm tại hội chợ','展会介绍产品','Thu hút khách ghé gian hàng và giới thiệu ngắn gọn.',
  'Bạn đứng gian hàng tại hội chợ thương mại, một khách Trung Quốc dừng lại xem.',
  ARRAY['Chào khách','Giới thiệu điểm nổi bật','Xin thông tin liên hệ'],'beginner',10,
  'Khách tham quan','参观客户','Tò mò, hỏi nhanh và dễ mất kiên nhẫn.','你们这个产品是做什么用的？',
  '[{"zh":"欢迎参观我们的展位。","vi":"Chào mừng đến gian hàng của chúng tôi."},{"zh":"可以留一下您的名片吗？","vi":"Tôi xin danh thiếp của quý khách được không?"}]'),
 ('Xuất nhập khẩu','Hỏi về chứng từ xuất khẩu','咨询出口单据','Xác nhận bộ chứng từ cần có cho lô hàng xuất.',
  'Đối tác hỏi bạn về các chứng từ đi kèm lô hàng sắp xuất.',
  ARRAY['Liệt kê chứng từ','Xác nhận bản gốc/bản sao','Hẹn thời gian gửi'],'advanced',15,
  'Đối tác Trung Quốc','中国合作伙伴','Cẩn thận, kiểm tra từng chi tiết.','请问出口需要准备哪些单据？',
  '[{"zh":"需要提单、发票和装箱单。","vi":"Cần vận đơn, hóa đơn và phiếu đóng gói."},{"zh":"我们会尽快寄原件。","vi":"Chúng tôi sẽ gửi bản gốc sớm nhất."}]'),
 ('Xuất nhập khẩu','Thương lượng điều khoản giao hàng','谈交货条款','Thống nhất thời hạn và phương thức giao hàng.',
  'Hai bên thảo luận ai chịu cước vận chuyển và ngày giao hàng.',
  ARRAY['Nêu điều kiện giao hàng','Thương lượng thời hạn','Chốt điều khoản'],'advanced',15,
  'Đối tác Trung Quốc','中国合作伙伴','Cứng rắn về thời hạn nhưng linh hoạt về giá.','关于交货时间，我们希望能提前一周。',
  '[{"zh":"我们需要和生产部门确认。","vi":"Chúng tôi cần xác nhận với bộ phận sản xuất."},{"zh":"运费由哪一方承担？","vi":"Bên nào chịu cước vận chuyển?"}]'),
 ('Xuất nhập khẩu','Thông báo lô hàng chậm trễ','货物延误通知','Báo tin chậm hàng và xin lỗi đối tác.',
  'Lô hàng bị trễ do thời tiết, bạn phải thông báo và đề xuất phương án.',
  ARRAY['Thông báo chậm trễ','Xin lỗi đúng mực','Đề xuất ngày giao mới'],'advanced',15,
  'Đối tác Trung Quốc','中国合作伙伴','Không hài lòng nhưng chịu nghe giải thích.','听说这批货会晚到，是真的吗？',
  '[{"zh":"因为天气原因，货物会延误两天。","vi":"Do thời tiết nên hàng sẽ chậm hai ngày."},{"zh":"非常抱歉，我们会全力补救。","vi":"Thành thật xin lỗi, chúng tôi sẽ cố gắng khắc phục."}]'),
 ('Du lịch - Dịch vụ','Hướng dẫn tham quan','带团参观','Giới thiệu điểm đến cho đoàn khách.',
  'Bạn hỗ trợ hướng dẫn viên dẫn đoàn khách Trung Quốc tham quan một danh thắng.',
  ARRAY['Giới thiệu điểm đến','Nhắc giờ tập trung','Trả lời câu hỏi của khách'],'intermediate',12,
  'Khách du lịch','游客','Vui vẻ, hay hỏi về lịch sử và đồ ăn.','这个地方有什么特别的历史吗？',
  '[{"zh":"请大家十二点在门口集合。","vi":"Mời mọi người tập trung ở cổng lúc 12 giờ."},{"zh":"这里已经有三百年的历史了。","vi":"Nơi này đã có lịch sử 300 năm."}]'),
 ('Du lịch - Dịch vụ','Hỗ trợ khách ở sân bay','机场接待','Đón khách và hướng dẫn thủ tục sau khi đáp.',
  'Bạn đến sân bay đón một đoàn khách và đưa họ lên xe.',
  ARRAY['Chào đón khách','Hỏi về hành lý','Hướng dẫn lên xe'],'beginner',10,
  'Khách du lịch','游客','Mệt sau chuyến bay, cần được hướng dẫn rõ ràng.','你好，请问去酒店的车在哪里？',
  '[{"zh":"欢迎来到越南！","vi":"Chào mừng đến Việt Nam!"},{"zh":"请跟我来，车在外面。","vi":"Xin đi theo tôi, xe ở bên ngoài."}]'),
 ('Nhân sự','Hỏi về lương và phúc lợi','询问薪资福利','Trao đổi chế độ thực tập và phụ cấp.',
  'Bạn hỏi bộ phận nhân sự về phụ cấp và thời gian làm việc của kỳ thực tập.',
  ARRAY['Hỏi lịch làm việc','Hỏi phụ cấp','Cảm ơn lịch sự'],'intermediate',12,
  'Quản lý nhân sự','人事经理','Rõ ràng, minh bạch về quy định công ty.','关于实习的待遇，你有什么想了解的吗？',
  '[{"zh":"请问实习期间有补贴吗？","vi":"Xin hỏi thời gian thực tập có phụ cấp không?"},{"zh":"每天的工作时间是几点到几点？","vi":"Mỗi ngày làm việc từ mấy giờ đến mấy giờ?"}]'),
 ('Nhân sự','Buổi đánh giá cuối kỳ thực tập','实习总结面谈','Tự đánh giá và nhận phản hồi từ quản lý.',
  'Kết thúc kỳ thực tập, quản lý gặp bạn để tổng kết.',
  ARRAY['Tự đánh giá','Nhận phản hồi','Nêu mong muốn tiếp theo'],'advanced',15,
  'Quản lý','经理','Thẳng thắn, ghi nhận cả điểm tốt và điểm cần cải thiện.','实习快结束了，你觉得自己有哪些收获？',
  '[{"zh":"我学到了很多实际工作经验。","vi":"Tôi học được nhiều kinh nghiệm làm việc thực tế."},{"zh":"我希望以后有机会继续在这里工作。","vi":"Tôi hy vọng sau này có cơ hội tiếp tục làm việc ở đây."}]'),
 ('Sản xuất - Nhà máy','Kiểm tra chất lượng sản phẩm','产品质量检查','Báo cáo kết quả kiểm tra lô sản phẩm.',
  'Bạn kiểm tra một lô hàng và báo cáo số lượng lỗi cho quản lý chất lượng.',
  ARRAY['Báo số lượng lỗi','Mô tả loại lỗi','Đề xuất xử lý'],'intermediate',12,
  'Quản lý chất lượng','质检经理','Tỉ mỉ, yêu cầu số liệu chính xác.','这批产品检查得怎么样了？',
  '[{"zh":"一共检查了五百件，有八件次品。","vi":"Tổng cộng kiểm 500 chiếc, có 8 chiếc lỗi."},{"zh":"主要问题是表面有划痕。","vi":"Lỗi chính là bề mặt bị xước."}]'),
 ('Sản xuất - Nhà máy','Nhận ca và bàn giao ca','交接班','Bàn giao tình trạng máy móc giữa hai ca làm việc.',
  'Hết ca, bạn bàn giao cho người ca sau tình hình dây chuyền.',
  ARRAY['Báo tình trạng máy','Nêu việc dang dở','Nhắc lưu ý an toàn'],'intermediate',10,
  'Tổ trưởng','组长','Bận, cần nghe ngắn gọn và đủ ý.','你好，上一班的情况怎么样？',
  '[{"zh":"二号机器运行正常。","vi":"Máy số 2 vận hành bình thường."},{"zh":"还有一批货没有包装完。","vi":"Còn một lô hàng chưa đóng gói xong."}]')
) AS s(cat, title, title_zh, description, situation, objectives, difficulty, minutes, ai_role, ai_role_zh, personality, initial_message, phrases)
JOIN public.categories c ON c.name = s.cat
WHERE NOT EXISTS (SELECT 1 FROM public.scenarios x WHERE x.title = s.title);

INSERT INTO public.vocabulary (category_id, chinese, pinyin, vietnamese, example_chinese, example_pinyin, example_vietnamese, difficulty)
SELECT c.id, v.zh, v.py, v.vi, v.ex, v.exp, v.exv, v.diff
FROM (VALUES
 ('Văn phòng - Hành chính','邮件','yóu jiàn','Email','我给你发了一封邮件。','Wǒ gěi nǐ fā le yì fēng yóujiàn.','Tôi đã gửi cho bạn một email.','beginner'),
 ('Văn phòng - Hành chính','打印','dǎ yìn','In ấn','请帮我打印这份文件。','Qǐng bāng wǒ dǎyìn zhè fèn wénjiàn.','Xin giúp tôi in tài liệu này.','beginner'),
 ('Văn phòng - Hành chính','日程','rì chéng','Lịch trình','这是今天的日程安排。','Zhè shì jīntiān de rìchéng ānpái.','Đây là lịch trình hôm nay.','intermediate'),
 ('Văn phòng - Hành chính','复印','fù yìn','Photocopy','请复印三份。','Qǐng fùyìn sān fèn.','Xin photo ba bản.','beginner'),
 ('Văn phòng - Hành chính','通知','tōng zhī','Thông báo','公司发了一个新通知。','Gōngsī fā le yí ge xīn tōngzhī.','Công ty vừa ra thông báo mới.','beginner'),
 ('Văn phòng - Hành chính','审批','shěn pī','Phê duyệt','这份申请还在审批中。','Zhè fèn shēnqǐng hái zài shěnpī zhōng.','Đơn này vẫn đang chờ phê duyệt.','advanced'),
 ('Văn phòng - Hành chính','预算','yù suàn','Ngân sách','今年的预算不多。','Jīnnián de yùsuàn bù duō.','Ngân sách năm nay không nhiều.','intermediate'),
 ('Văn phòng - Hành chính','同意','tóng yì','Đồng ý','经理同意了我的方案。','Jīnglǐ tóngyì le wǒ de fāng''àn.','Quản lý đã đồng ý phương án của tôi.','beginner'),
 ('Văn phòng - Hành chính','安排','ān pái','Sắp xếp','请安排一下会议室。','Qǐng ānpái yíxià huìyìshì.','Xin sắp xếp phòng họp.','intermediate'),
 ('Kinh doanh - Bán hàng','样品','yàng pǐn','Hàng mẫu','我们可以先寄样品。','Wǒmen kěyǐ xiān jì yàngpǐn.','Chúng tôi có thể gửi hàng mẫu trước.','intermediate'),
 ('Kinh doanh - Bán hàng','库存','kù cún','Tồn kho','现在库存不多了。','Xiànzài kùcún bù duō le.','Hiện tồn kho không còn nhiều.','intermediate'),
 ('Kinh doanh - Bán hàng','付款','fù kuǎn','Thanh toán','请在三天内付款。','Qǐng zài sān tiān nèi fùkuǎn.','Xin thanh toán trong ba ngày.','beginner'),
 ('Kinh doanh - Bán hàng','发票','fā piào','Hóa đơn','需要开发票吗？','Xūyào kāi fāpiào ma?','Có cần xuất hóa đơn không?','beginner'),
 ('Kinh doanh - Bán hàng','谈判','tán pàn','Đàm phán','双方正在谈判。','Shuāngfāng zhèngzài tánpàn.','Hai bên đang đàm phán.','advanced'),
 ('Kinh doanh - Bán hàng','市场','shì chǎng','Thị trường','我们想开拓中国市场。','Wǒmen xiǎng kāituò Zhōngguó shìchǎng.','Chúng tôi muốn mở rộng thị trường Trung Quốc.','intermediate'),
 ('Kinh doanh - Bán hàng','促销','cù xiāo','Khuyến mãi','这个月有促销活动。','Zhège yuè yǒu cùxiāo huódòng.','Tháng này có chương trình khuyến mãi.','intermediate'),
 ('Kinh doanh - Bán hàng','退货','tuì huò','Trả hàng','七天内可以退货。','Qī tiān nèi kěyǐ tuìhuò.','Trong bảy ngày có thể trả hàng.','intermediate'),
 ('Kinh doanh - Bán hàng','竞争','jìng zhēng','Cạnh tranh','市场竞争很激烈。','Shìchǎng jìngzhēng hěn jīliè.','Cạnh tranh thị trường rất gay gắt.','advanced'),
 ('Xuất nhập khẩu','出口','chū kǒu','Xuất khẩu','我们公司主要做出口。','Wǒmen gōngsī zhǔyào zuò chūkǒu.','Công ty chúng tôi chủ yếu làm xuất khẩu.','beginner'),
 ('Xuất nhập khẩu','进口','jìn kǒu','Nhập khẩu','这些设备是进口的。','Zhèxiē shèbèi shì jìnkǒu de.','Những thiết bị này là hàng nhập khẩu.','beginner'),
 ('Xuất nhập khẩu','关税','guān shuì','Thuế quan','关税是多少？','Guānshuì shì duōshao?','Thuế quan là bao nhiêu?','intermediate'),
 ('Xuất nhập khẩu','提单','tí dān','Vận đơn','请把提单发给我。','Qǐng bǎ tídān fā gěi wǒ.','Xin gửi vận đơn cho tôi.','advanced'),
 ('Xuất nhập khẩu','装运','zhuāng yùn','Vận chuyển / bốc hàng','货物已经装运了。','Huòwù yǐjīng zhuāngyùn le.','Hàng đã được bốc lên tàu.','intermediate'),
 ('Xuất nhập khẩu','信用证','xìn yòng zhèng','Thư tín dụng (L/C)','我们用信用证付款。','Wǒmen yòng xìnyòngzhèng fùkuǎn.','Chúng tôi thanh toán bằng L/C.','advanced'),
 ('Xuất nhập khẩu','原产地证','yuán chǎn dì zhèng','Giấy chứng nhận xuất xứ (C/O)','请提供原产地证。','Qǐng tígōng yuánchǎndì zhèng.','Xin cung cấp giấy chứng nhận xuất xứ.','advanced'),
 ('Xuất nhập khẩu','仓库','cāng kù','Kho hàng','货物放在仓库里。','Huòwù fàng zài cāngkù lǐ.','Hàng để trong kho.','beginner'),
 ('Xuất nhập khẩu','延误','yán wu','Chậm trễ','航班延误了两小时。','Hángbān yánwu le liǎng xiǎoshí.','Chuyến bay bị chậm hai tiếng.','intermediate'),
 ('Du lịch - Dịch vụ','机票','jī piào','Vé máy bay','我已经订好机票了。','Wǒ yǐjīng dìng hǎo jīpiào le.','Tôi đã đặt xong vé máy bay.','beginner'),
 ('Du lịch - Dịch vụ','护照','hù zhào','Hộ chiếu','请出示您的护照。','Qǐng chūshì nín de hùzhào.','Xin xuất trình hộ chiếu.','beginner'),
 ('Du lịch - Dịch vụ','行程','xíng chéng','Lịch trình chuyến đi','明天的行程很满。','Míngtiān de xíngchéng hěn mǎn.','Lịch trình ngày mai rất kín.','intermediate'),
 ('Du lịch - Dịch vụ','景点','jǐng diǎn','Điểm tham quan','这个景点很有名。','Zhège jǐngdiǎn hěn yǒumíng.','Điểm tham quan này rất nổi tiếng.','beginner'),
 ('Du lịch - Dịch vụ','翻译','fān yì','Phiên dịch','我来给大家翻译。','Wǒ lái gěi dàjiā fānyì.','Để tôi phiên dịch cho mọi người.','beginner'),
 ('Du lịch - Dịch vụ','地图','dì tú','Bản đồ','这是景区的地图。','Zhè shì jǐngqū de dìtú.','Đây là bản đồ khu tham quan.','beginner'),
 ('Du lịch - Dịch vụ','行李','xíng li','Hành lý','我来帮您拿行李。','Wǒ lái bāng nín ná xíngli.','Để tôi giúp quý khách xách hành lý.','beginner'),
 ('Du lịch - Dịch vụ','门票','mén piào','Vé vào cửa','门票一人五十元。','Ménpiào yì rén wǔshí yuán.','Vé vào cửa 50 tệ một người.','beginner'),
 ('Du lịch - Dịch vụ','换房','huàn fáng','Đổi phòng','我想换一间房。','Wǒ xiǎng huàn yì jiān fáng.','Tôi muốn đổi phòng.','intermediate'),
 ('Nhân sự','招聘','zhāo pìn','Tuyển dụng','公司正在招聘新员工。','Gōngsī zhèngzài zhāopìn xīn yuángōng.','Công ty đang tuyển nhân viên mới.','intermediate'),
 ('Nhân sự','应聘','yìng pìn','Ứng tuyển','我来应聘市场助理。','Wǒ lái yìngpìn shìchǎng zhùlǐ.','Tôi đến ứng tuyển trợ lý marketing.','intermediate'),
 ('Nhân sự','福利','fú lì','Phúc lợi','公司的福利很好。','Gōngsī de fúlì hěn hǎo.','Phúc lợi của công ty rất tốt.','intermediate'),
 ('Nhân sự','试用期','shì yòng qī','Thời gian thử việc','试用期是三个月。','Shìyòngqī shì sān ge yuè.','Thời gian thử việc là ba tháng.','intermediate'),
 ('Nhân sự','考勤','kǎo qín','Chấm công','每天都要打卡考勤。','Měitiān dōu yào dǎkǎ kǎoqín.','Mỗi ngày đều phải chấm công.','intermediate'),
 ('Nhân sự','绩效','jì xiào','Hiệu suất công việc','年底会做绩效评估。','Niándǐ huì zuò jìxiào pínggū.','Cuối năm sẽ đánh giá hiệu suất.','advanced'),
 ('Nhân sự','离职','lí zhí','Nghỉ việc','他下个月离职。','Tā xià ge yuè lízhí.','Tháng sau anh ấy nghỉ việc.','intermediate'),
 ('Nhân sự','晋升','jìn shēng','Thăng chức','她今年得到了晋升。','Tā jīnnián dédào le jìnshēng.','Năm nay cô ấy được thăng chức.','advanced'),
 ('Nhân sự','面试官','miàn shì guān','Người phỏng vấn','面试官问了很多问题。','Miànshìguān wèn le hěn duō wèntí.','Người phỏng vấn hỏi rất nhiều câu.','intermediate'),
 ('Sản xuất - Nhà máy','原材料','yuán cái liào','Nguyên vật liệu','原材料价格上涨了。','Yuáncáiliào jiàgé shàngzhǎng le.','Giá nguyên vật liệu đã tăng.','intermediate'),
 ('Sản xuất - Nhà máy','产量','chǎn liàng','Sản lượng','这个月产量提高了。','Zhège yuè chǎnliàng tígāo le.','Tháng này sản lượng tăng.','intermediate'),
 ('Sản xuất - Nhà máy','包装','bāo zhuāng','Đóng gói','产品已经包装好了。','Chǎnpǐn yǐjīng bāozhuāng hǎo le.','Sản phẩm đã đóng gói xong.','beginner'),
 ('Sản xuất - Nhà máy','维修','wéi xiū','Sửa chữa, bảo trì','机器需要维修。','Jīqì xūyào wéixiū.','Máy cần được bảo trì.','intermediate'),
 ('Sản xuất - Nhà máy','操作','cāo zuò','Vận hành, thao tác','请按规定操作。','Qǐng àn guīdìng cāozuò.','Xin thao tác theo quy định.','beginner'),
 ('Sản xuất - Nhà máy','事故','shì gù','Tai nạn, sự cố','昨天发生了一起事故。','Zuótiān fāshēng le yì qǐ shìgù.','Hôm qua đã xảy ra một sự cố.','intermediate'),
 ('Sản xuất - Nhà máy','次品','cì pǐn','Hàng lỗi','次品要单独放。','Cìpǐn yào dāndú fàng.','Hàng lỗi phải để riêng.','intermediate'),
 ('Sản xuất - Nhà máy','设备','shè bèi','Thiết bị','这些设备很先进。','Zhèxiē shèbèi hěn xiānjìn.','Những thiết bị này rất hiện đại.','intermediate'),
 ('Sản xuất - Nhà máy','夜班','yè bān','Ca đêm','他今天上夜班。','Tā jīntiān shàng yèbān.','Hôm nay anh ấy làm ca đêm.','beginner')
